ALTER TABLE `households` ADD `category_labels` text DEFAULT '{}' NOT NULL;--> statement-breakpoint
UPDATE `households` SET `gift_categories` = '["home"]' WHERE `gift_categories` = '["homecooked","houseparty","round","fika"]';--> statement-breakpoint
UPDATE `households` SET `gift_categories` = (SELECT COALESCE(json_group_array(k), '[]') FROM (SELECT DISTINCT CASE value WHEN 'homecooked' THEN 'home' WHEN 'houseparty' THEN 'home' WHEN 'round' THEN 'drinks' WHEN 'fika' THEN 'other' ELSE value END AS k FROM json_each(`households`.`gift_categories`))) WHERE json_valid(`gift_categories`) AND (`gift_categories` LIKE '%homecooked%' OR `gift_categories` LIKE '%houseparty%' OR `gift_categories` LIKE '%"round"%' OR `gift_categories` LIKE '%"fika"%');--> statement-breakpoint
UPDATE `expenses` SET `category` = CASE `category` WHEN 'homecooked' THEN 'home' WHEN 'houseparty' THEN 'home' WHEN 'round' THEN 'drinks' WHEN 'fika' THEN 'other' END WHERE `category` IN ('homecooked', 'houseparty', 'round', 'fika');
